content:
:root {
  --bg-color: #1a1a1a;
  --panel-bg: #2d2d2d;
  --text-color: #f0f0f0;
  --text-subtitle: #aaa;
  --white-key-bg: #ffffff;
  --white-key-active: #e0e0e0;
  --black-key-bg: #222222;
  --black-key-active: #444444;
  --accent-color: #4f46e5;
  --accent-hover: #4338ca;
  --border-color: #444;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  user-select: none;
  -webkit-user-select: none;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  width: 100%;
  max-width: 800px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  align-items: center;
}

.piano-header {
  text-align: center;
  margin-bottom: 10px;
}

.piano-title {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 5px;
  background: linear-gradient(135deg, #fff 0%, #aaa 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.piano-subtitle {
  font-size: 0.95rem;
  color: var(--text-subtitle);
}

.keyboard-container {
  background: var(--panel-bg);
  padding: 30px 20px;
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--border-color);
}

.keyboard {
  position: relative;
  display: flex;
  height: 220px;
}

.key {
  position: relative;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 15px;
  transition: background 0.1s ease, transform 0.05s ease;
  touch-action: none;
}

.white-key {
  width: 50px;
  height: 200px;
  background-color: var(--white-key-bg);
  border: 1px solid #ccc;
  border-radius: 0 0 6px 6px;
  z-index: 1;
  color: #333;
}

.white-key.active {
  background-color: var(--white-key-active);
  transform: translateY(2px);
  box-shadow: inset 0 4px 6px rgba(0, 0, 0, 0.2);
}

.black-key {
  position: absolute;
  width: 32px;
  height: 120px;
  background-color: var(--black-key-bg);
  border-radius: 0 0 4px 4px;
  z-index: 2;
  color: #fff;
  border: 1px solid #000;
}

.black-key.active {
  background-color: var(--black-key-active);
  transform: translateY(2px);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.5);
}

.key-label {
  font-size: 0.85rem;
  font-weight: bold;
}

.key-bind {
  font-size: 0.75rem;
  opacity: 0.7;
  margin-top: 2px;
  background: rgba(0, 0, 0, 0.08);
  padding: 2px 6px;
  border-radius: 4px;
}

.black-key .key-bind {
  background: rgba(255, 255, 255, 0.2);
}

.control-panel {
  display: flex;
  gap: 10px;
  justify-content: center;
  width: 100%;
}

.btn {
  background-color: var(--accent-color);
  color: white;
  border: none;
  padding: 10px 20px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s ease, transform 0.1s ease;
  box-shadow: 0 4px 10px rgba(79, 70, 229, 0.3);
}

.btn:hover {
  background-color: var(--accent-hover);
}

.btn:active {
  transform: scale(0.98);
}

.history-panel {
  background: var(--panel-bg);
  padding: 20px;
  border-radius: 16px;
  width: 100%;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  border: 1px solid var(--border-color);
}

.history-title {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 12px;
  color: var(--text-color);
}

.history-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  max-height: 100px;
  overflow-y: auto;
}

.history-item {
  background: #3a3a3a;
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 0.85rem;
  display: flex;
  gap: 8px;
  align-items: center;
  border: 1px solid #555;
}

.history-time {
  color: var(--text-subtitle);
  font-size: 0.75rem;
}

@media (max-width: 600px) {
  .app-container {
    padding: 10px;
  }
  .white-key {
    width: 40px;
    height: 160px;
  }
  .black-key {
    width: 24px;
    height: 95px;
  }
  .keyboard {
    height: 180px;
  }
  .piano-title {
    font-size: 1.5rem;
  }
}

export interface KeyNote {
  id: string;
  name: string;
  note: string;
  frequency: number;
  isBlack: boolean;
  keyBind: string;
}

export interface PlayedNote {
  id: string;
  name: string;
  timestamp: string;
}

import { useState, useRef, useEffect, useCallback } from 'react';
import { KeyNote } from '../types';
import '../index.css';

const KEYS: KeyNote[] = [
  { id: 'C4', name: 'C', note: 'ド', frequency: 261.63, isBlack: false, keyBind: 'A' },
  { id: 'C#4', name: 'C#', note: 'ド#', frequency: 277.18, isBlack: true, keyBind: 'W' },
  { id: 'D4', name: 'D', note: 'レ', frequency: 293.66, isBlack: false, keyBind: 'S' },
  { id: 'D#4', name: 'D#', note: 'レ#', frequency: 311.13, isBlack: true, keyBind: 'E' },
  { id: 'E4', name: 'E', note: 'ミ', frequency: 329.63, isBlack: false, keyBind: 'D' },
  { id: 'F4', name: 'F', note: 'ファ', frequency: 349.23, isBlack: false, keyBind: 'F' },
  { id: 'F#4', name: 'F#', note: 'ファ#', frequency: 369.99, isBlack: true, keyBind: 'T' },
  { id: 'G4', name: 'G', note: 'ソ', frequency: 392.00, isBlack: false, keyBind: 'G' },
  { id: 'G#4', name: 'G#', note: 'ソ#', frequency: 415.30, isBlack: true, keyBind: 'Y' },
  { id: 'A4', name: 'A', note: 'ラ', frequency: 440.00, isBlack: false, keyBind: 'H' },
  { id: 'A#4', name: 'A#', note: 'ラ#', frequency: 466.16, isBlack: true, keyBind: 'U' },
  { id: 'B4', name: 'B', note: 'シ', frequency: 493.88, isBlack: false, keyBind: 'J' },
  { id: 'C5', name: 'C5', note: '高ド', frequency: 523.25, isBlack: false, keyBind: 'K' },
];

interface PianoProps {
  onPlayNote: (note: KeyNote) => void;
}

export default function Piano({ onPlayNote }: PianoProps) {
  const [activeKeys, setActiveKeys] = useState<Record<string, boolean>>({});
  const audioCtxRef = useRef<AudioContext | null>(null);

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      audioCtxRef.current = new AudioContextClass();
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  };

  const playSound = useCallback((frequency: number) => {
    try {
      const ctx = getAudioContext();
      const osc = ctx.createOscillator();
      const gainNode = ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(frequency, ctx.currentTime);

      gainNode.gain.setValueAtTime(0.3, ctx.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1);

      osc.connect(gainNode);
      gainNode.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + 1);
    } catch (e) {
      console.error(e);
    }
  }, []);

  const triggerNote = useCallback((keyNote: KeyNote) => {
    playSound(keyNote.frequency);
    onPlayNote(keyNote);
    setActiveKeys((prev) => ({ ...prev, [keyNote.id]: true }));

    setTimeout(() => {
      setActiveKeys((prev) => ({ ...prev, [keyNote.id]: false }));
    }, 150);
  }, [playSound, onPlayNote]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      const found = KEYS.find((k) => k.keyBind.toLowerCase() === e.key.toLowerCase());
      if (found) {
        triggerNote(found);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [triggerNote]);

  // 黒鍵の配置計算用インデックス (白鍵基準)
  let whiteKeyIndex = 0;

  return (
    <div className="keyboard-container">
      <div className="keyboard">
        {KEYS.map((key) => {
          const isActive = activeKeys[key.id] || false;
          let style = {};

          if (!key.isBlack) {
            whiteKeyIndex++;
          } else {
            // 黒鍵の絶対位置調整 (白鍵の幅50pxを基準に配置)
            const leftPos = (whiteKeyIndex * 50) - 16;
            style = { left: `${leftPos}px` };
          }

          const className = key.isBlack
            ? `key black-key ${isActive ? 'active' : ''}`
            : `key white-key ${isActive ? 'active' : ''}`;

          return (
            <div
              key={key.id}
              className={className}
              style={style}
              onPointerDown={(e) => {
                e.preventDefault();
                triggerNote(key);
              }}
            >
              <span className="key-label">{key.note}</span>
              <span className="key-bind">{key.keyBind}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState } from 'react';
import Piano from './components/Piano';
import { KeyNote, PlayedNote } from './types';
import './index.css';

export default function App() {
  const [history, setHistory] = useState<PlayedNote[]>([]);

  const handlePlayNote = (note: KeyNote) => {
    const now = new Date();
    const timestamp = now.toLocaleTimeString() + '.' + Math.floor(now.getMilliseconds() / 100);
    const newPlayedNote: PlayedNote = {
      id: `${note.id}-${Date.now()}-${Math.random()}`,
      name: `${note.note} (${note.name})`,
      timestamp,
    };
    setHistory((prev) => [newPlayedNote, ...prev].slice(0, 20));
  };

  const clearHistory = () => {
    setHistory([]);
  };

  return (
    <div className="app-container">
      <header className="piano-header">
        <h1 className="piano-title">Webピアノ</h1>
        <p className="piano-subtitle">1オクターブの鍵盤をタッチ、クリック、またはキーボード（A-K, W-U）で演奏しよう</p>
      </header>

      <Piano onPlayNote={handlePlayNote} />

      <div className="control-panel">
        <button className="btn" onClick={clearHistory}>
          履歴をクリア
        </button>
      </div>

      <div className="history-panel">
        <h2 className="history-title">演奏履歴</h2>
        <div className="history-list">
          {history.length === 0 ? (
            <p className="piano-subtitle">まだ演奏されていません。鍵盤を押してみましょう！</p>
          ) : (
            history.map((item) => (
              <div key={item.id} className="history-item">
                <span>{item.name}</span>
                <span className="history-time">{item.timestamp}</span>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}
